package pyjvm315.runtime;

/**
 * The integer constants of {@code fcntl}, {@code termios} and {@code resource} on Linux x86-64 (glibc), generated by
 * {@code tools/gen_posix_tables.py --consts fcntl|termios|resource} under a Linux CPython (identical on 3.13, 3.14 and
 * 3.15). Names are sorted, the {@code long} values are parallel by index. {@code RLIM_INFINITY}, {@code RLIM_SAVED_CUR}
 * and {@code RLIM_SAVED_MAX} are left out: their value depends on the lane and is set by the module. Data only: no FFM
 * import, safe to load anywhere (it is still only reached from the POSIX modules).
 */
